def find_longest_palindrome(s):
    n = len(s)
    max_length = 0
    result = ""

    # Check all possible palindromes
    for i in range(n):
        for j in range(i, n):
            substring = s[i:j+1]
            if substring == substring[::-1]:  # Check if it's a palindrome
                if s.startswith(substring[:i+1]) and s.endswith(substring[j:]):
                    if len(substring) > max_length:
                        max_length = len(substring)
                        result = substring

    return result

